export interface ConnectorConfig {
  zendeskSubdomain: string
  zendeskAccessToken: string
  intercomWebhookSecret?: string
  fetch?: typeof fetch
}

export interface IntercomWebhookPayload {
  type: string
  id: string
  topic: string
  app_id: string
  created_at: number
  delivery_attempts: number
  first_sent_at: number
  data: {
    item: {
      type: string
      id: string
      url: string
      tags: Array<{ id: string; name: string; type: string }>
    }
  }
}

export interface HandleResult {
  ticketId: number
  subject: string
  createdAt: string
}

function validatePayload(payload: unknown): IntercomWebhookPayload {
  if (!payload || typeof payload !== 'object') {
    throw new Error('Payload must be an object')
  }
  const p = payload as Record<string, unknown>
  if (p.topic !== 'conversation_part.tag.created') {
    throw new Error(`Expected topic "conversation_part.tag.created", got "${p.topic}"`)
  }
  if (!p.data || typeof p.data !== 'object') {
    throw new Error('Missing data object')
  }
  const data = p.data as Record<string, unknown>
  if (!data.item || typeof data.item !== 'object') {
    throw new Error('Missing data.item object')
  }
  const item = data.item as Record<string, unknown>
  if (item.type !== 'conversation') {
    throw new Error(`Expected item type "conversation", got "${item.type}"`)
  }
  if (typeof item.id !== 'string' || !item.id) {
    throw new Error('Missing or invalid conversation id')
  }
  if (typeof item.url !== 'string' || !item.url) {
    throw new Error('Missing or invalid conversation url')
  }
  if (!Array.isArray(item.tags)) {
    throw new Error('Missing tags array')
  }
  const hasRefundTag = item.tags.some(
    (tag: unknown) => tag && typeof tag === 'object' && (tag as Record<string, unknown>).name === 'refund'
  )
  if (!hasRefundTag) {
    throw new Error('Conversation does not have the "refund" tag')
  }
  return payload as IntercomWebhookPayload
}

export async function handle(
  payload: unknown,
  config: ConnectorConfig
): Promise<HandleResult> {
  const validated = validatePayload(payload)
  const conversation = validated.data.item
  const fetchImpl = config.fetch ?? fetch

  const ticketBody = {
    ticket: {
      subject: conversation.id,
      comment: {
        body: `Conversation link: ${conversation.url}`
      }
    }
  }

  const url = `https://${config.zendeskSubdomain}.zendesk.com/api/v2/tickets.json`
  const response = await fetchImpl(url, {
    method: 'POST',
    headers: {
      'Authorization': `Bearer ${config.zendeskAccessToken}`,
      'Content-Type': 'application/json'
    },
    body: JSON.stringify(ticketBody)
  })

  if (!response.ok) {
    throw new Error(`Zendesk API error: ${response.status} ${response.statusText} for POST ${url}`)
  }

  const result = await response.json() as { ticket: { id: number; subject: string; created_at: string } }
  return {
    ticketId: result.ticket.id,
    subject: result.ticket.subject,
    createdAt: result.ticket.created_at
  }
}

import { describe, it, expect, vi } from 'vitest'
import { handle, ConnectorConfig, IntercomWebhookPayload } from './connector'
