describe('contract', () => {
  it('handles the documented example payload', async () => {
    const { fetch, calls } = contractFetch()
    const config: ConnectorConfig = {
      zendeskSubdomain: 'example',
      zendeskAccessToken: 'test-token',
      fetch
    }
    const result = await handle(SOURCE_EXAMPLE as unknown as IntercomWebhookPayload, config)
    expect(calls.length).toBeGreaterThan(0)
    expect(result.ticketId).toBe(12345)
    expect(result.subject).toBe('conv_123')
  })
})

describe('handle', () => {
  it('creates a Zendesk ticket with correct subject and comment', async () => {
    const { fetch, calls } = fakeFetch((req: RecordedCall) => {
      expect(req.method).toBe('POST')
      expect(req.url).toBe('https://test.zendesk.com/api/v2/tickets.json')
      expect(req.headers.get('authorization')).toBe('Bearer secret-token')
