        ticket: {
          subject: 'conv_123',
          comment: { body: 'Conversation link: https://app.intercom.io/a/apps/a86dr8yl/conversations/conv_123' }
        }
      })
      return jsonResponse({
        ticket: { id: 999, subject: 'conv_123', created_at: '2024-01-01T00:00:00Z' }
      }, 201)
    })

    const payload: IntercomWebhookPayload = {
      type: 'notification_event',
      id: 'notif_1',
      topic: 'conversation_part.tag.created',
      app_id: 'app_1',
      created_at: 1700000000,
      delivery_attempts: 1,
      first_sent_at: 1700000000,
      data: {
        item: {
          type: 'conversation',
          id: 'conv_123',
          url: 'https://app.intercom.io/a/apps/a86dr8yl/conversations/conv_123',
          tags: [{ id: 'tag_1', name: 'refund', type: 'tag' }]
        }
      }
    }

    const config: ConnectorConfig = {
      zendeskSubdomain: 'test',
      zendeskAccessToken: 'secret-token',
      fetch
