    const result = await handle(payload, config)
    expect(result).toEqual({
      ticketId: 999,
      subject: 'conv_123',
      createdAt: '2024-01-01T00:00:00Z'
    })
    expect(calls.length).toBe(1)
  })

  it('throws when topic is not conversation_part.tag.created', async () => {
    const { fetch } = fakeFetch(() => jsonResponse({}, 200))
    const payload = { ...SOURCE_EXAMPLE, topic: 'other.topic' }
    const config: ConnectorConfig = { zendeskSubdomain: 'test', zendeskAccessToken: 'token', fetch }
    await expect(handle(payload as unknown as IntercomWebhookPayload, config)).rejects.toThrow(
      /Expected topic "conversation_part.tag.created"/
    )
  })

  it('throws when conversation id is missing', async () => {
    const { fetch } = fakeFetch(() => jsonResponse({}, 200))
