  it('throws when conversation url is missing', async () => {
    const { fetch } = fakeFetch(() => jsonResponse({}, 200))
    const payload = {
      ...SOURCE_EXAMPLE,
      data: { item: { ...SOURCE_EXAMPLE.data.item, url: '' } }
    }
    const config: ConnectorConfig = { zendeskSubdomain: 'test', zendeskAccessToken: 'token', fetch }
    await expect(handle(payload as unknown as IntercomWebhookPayload, config)).rejects.toThrow(
