    )
  })

  it('throws when refund tag is not present', async () => {
    const { fetch } = fakeFetch(() => jsonResponse({}, 200))
    const payload = {
      ...SOURCE_EXAMPLE,
      data: { item: { ...SOURCE_EXAMPLE.data.item, tags: [{ id: 'tag_1', name: 'other', type: 'tag' }] } }
    }
    const config: ConnectorConfig = { zendeskSubdomain: 'test', zendeskAccessToken: 'token', fetch }
    await expect(handle(payload as unknown as IntercomWebhookPayload, config)).rejects.toThrow(
      /does not have the "refund" tag/
    )
  })

  it('throws on non-2xx response from Zendesk', async () => {
    const { fetch, calls } = fakeFetch(() => jsonResponse({ error: 'Unauthorized' }, 401))
    const payload: IntercomWebhookPayload = {
      type: 'notification_event',
      id: 'notif_1',
      topic: 'conversation_part.tag.created',
      app_id: 'app_1',
      created_at: 1700000000,
      delivery_attempts: 1,
      first_sent_at: 1700000000,
      data: {
        item: {
          type: 'conversation',
          id: 'conv_123',
          url: 'https://app.intercom.io/a/apps/a86dr8yl/conversations/conv_123',
          tags: [{ id: 'tag_1', name: 'refund', type: 'tag' }]
        }
      }
    }
    const config: ConnectorConfig = { zendeskSubdomain: 'test', zendeskAccessToken: 'bad-token', fetch }
    await expect(handle(payload, config)).rejects.toThrow(
      /Zendesk API error: 401 Unauthorized for POST https:\/\/test\.zendesk\.com\/api\/v2\/tickets\.json/
    )
    expect(calls.length).toBe(1)
  })

  it('uses injected fetch from config', async () => {
    const { fetch, calls } = fakeFetch(() => jsonResponse({
      ticket: { id: 1, subject: 'conv_1', created_at: '2024-01-01T00:00:00Z' }
    }, 201))
    const payload: IntercomWebhookPayload = {
      type: 'notification_event',
      id: 'notif_1',
